<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
require_once __DIR__.'/Support/ReviewedListingFixture.php';
require_once __DIR__.'/Support/SyntheticEtsyIdentity.php';
