use DigiForge\Database\Tables;
use DigiForge\Listings\PublishReviewRepository;
final class PublishReviewAcceptanceTest extends WP_UnitTestCase {
 private mixed $guard;private int $http=0;
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();ShopAccessFixture::reset();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['digital','personalized_pod','standard_pod','jewelry'],DigiForge\Core\Capabilities::ALL);$this->guard=function(){++$this->http;return new WP_Error('offline_publish_review','HTTP forbidden.');};add_filter('pre_http_request',$this->guard);}
 protected function tearDown():void {remove_filter('pre_http_request',$this->guard);self::assertSame(0,$this->http);self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));parent::tearDown();}
 private function fixture():array {
  $f=ReviewedListingFixture::create($this);$qa=new DigiForge\Listings\DraftQaReviewRepository();$context=$qa->inspect($f['create']);self::assertNotWPError($context);self::assertNotWPError($qa->record($f['intent'],$f['package'],$f['create'],array_fill_keys(['title','description','seo','media','pricing','policy','personalization'],'PASS'),'CONFIRM_DRAFT_QA_REVIEW',$context['objective_evidence_hash']));global $wpdb;$now=current_time('mysql',true);$integration=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.Tables::integrations().' WHERE connection_key=%s AND environment=%s LIMIT 1','publish-review-synthetic-seller-v2','sandbox'));if($integration===0){self::assertSame(1,$wpdb->insert(Tables::integrations(),['provider'=>'etsy','connection_key'=>'publish-review-synthetic-seller-v2','display_name'=>'Synthetic offline seller identity','environment'=>'sandbox','status'=>'CONFIGURED','enabled'=>1,'config'=>SyntheticEtsyIdentity::config('1234','digital'),'created_at'=>$now,'updated_at'=>$now]));$integration=(int)$wpdb->insert_id;SyntheticEtsyIdentity::credential($integration);}return $f+['input'=>['shop_key'=>'digital','integration_id'=>$integration,'shop_id'=>1234,'intent_id'=>$f['intent'],'draft_package_id'=>$f['package']]];
 }
 public function testSeparateHumanReviewPersistsExactScopeAndConsumptionIsOneUseWithoutActivatingAnything():void {
  $f=$this->fixture();$repo=new PublishReviewRepository();$c=$repo->inspect($f['input']);self::assertNotWPError($c);self::assertWPError($repo->record($f['input'],$c['scope_hash'],'unchecked'));$r=$repo->record($f['input'],$c['scope_hash'],'CONFIRM_SEPARATE_PUBLISH_REVIEW');self::assertNotWPError($r);$id=$r['payload']['review_id'];self::assertFalse($r['publish_authorized']);self::assertNotWPError($repo->verify($id,$c));$approval=$repo->consume($id,$c,'review-test-key');self::assertNotWPError($approval);self::assertSame('HUMAN_APPROVED',$approval['state']);self::assertSame(get_current_user_id(),$approval['approved_by']);self::assertSame($c['request_fingerprint'],$approval['request_fingerprint']);self::assertFalse($approval['publishing_enabled']);self::assertWPError($repo->consume($id,$c,'another-key'));self::assertSame('CONSUMED',$repo->status($id)['state']);$nonce=str_replace('-','_',wp_generate_uuid4());$issuer=DigiForge\POD\ExecutionAuthorization::class;self::assertWPError($issuer::issue($approval,'PROVIDER_ORDER_SUBMIT',get_current_user_id(),$nonce,300,$c['request_fingerprint']));self::assertWPError($issuer::issue($approval,'ETSY_PUBLISH_LISTING',get_current_user_id()+1,$nonce,300,$c['request_fingerprint']));self::assertWPError($issuer::issue($approval,'ETSY_PUBLISH_LISTING',get_current_user_id(),$nonce,300,hash('sha256','other-request')));$authorization=$issuer::issue($approval,'ETSY_PUBLISH_LISTING',get_current_user_id(),$nonce,300,$c['request_fingerprint']);self::assertNotWPError($authorization);$claim=static fn(string $token)=>DigiForge\POD\ExecutionNonceLedger::consume($token,$authorization['authorization_hash'],get_current_user_id());self::assertTrue(DigiForge\POD\ExecutionAuthorizationVerifier::verify($authorization,'ETSY_PUBLISH_LISTING',$c['readiness_hash'],time(),$claim));self::assertWPError(DigiForge\POD\ExecutionAuthorizationVerifier::verify($authorization,'ETSY_PUBLISH_LISTING',$c['readiness_hash'],time(),$claim));
 }
 public function testChangedEvidenceTamperingCopiedReceiptAndForeignScopeCannotAuthorize():void {
  $f=$this->fixture();$repo=new PublishReviewRepository();$c=$repo->inspect($f['input']);self::assertNotWPError($c);$r=$repo->record($f['input'],$c['scope_hash'],'CONFIRM_SEPARATE_PUBLISH_REVIEW');self::assertNotWPError($r);$id=$r['payload']['review_id'];$alias=wp_generate_uuid4();self::assertTrue(add_option(PublishReviewRepository::PREFIX.$alias,wp_json_encode($r),'',false));self::assertWPError($repo->verify($alias,$c));$changed=$c;$changed['scope_hash']=hash('sha256','changed');self::assertWPError($repo->verify($id,$changed));self::assertWPError($repo->inspect(array_replace($f['input'],['shop_key'=>'jewelry'])));self::assertWPError($repo->inspect(array_replace($f['input'],['shop_id'=>99999])));$r['payload']['actor_id']++;update_option(PublishReviewRepository::PREFIX.$id,wp_json_encode($r),false);self::assertWPError($repo->verify($id,$c));
 }
 public function testStoredIntegrationDriftAndAuditReadFaultBlockReviewWithoutCredentialsOrHttp():void {
  $f=$this->fixture();$repo=new PublishReviewRepository();$c=$repo->inspect($f['input']);self::assertNotWPError($c);global $wpdb;$wpdb->update(Tables::integrations(),['enabled'=>0],['id'=>$f['input']['integration_id']]);self::assertWPError($repo->record($f['input'],$c['scope_hash'],'CONFIRM_SEPARATE_PUBLISH_REVIEW'));$wpdb->update(Tables::integrations(),['enabled'=>1],['id'=>$f['input']['integration_id']]);$filter=static fn(string $sql):string=>str_starts_with($sql,'INSERT INTO `'.Tables::audit_log().'`')?'INSERT INTO missing_publish_review_audit (id) VALUES (1)':$sql;$old=$wpdb->suppress_errors(true);add_filter('query',$filter);try{self::assertWPError($repo->record($f['input'],$c['scope_hash'],'CONFIRM_SEPARATE_PUBLISH_REVIEW'));}finally{remove_filter('query',$filter);$wpdb->suppress_errors($old);}wp_set_current_user(0);self::assertWPError($repo->inspect($f['input']));
 }
 public function testActualPortalShowsExactSeparateDecisionAndNativeActionRecordsWithoutPublishing():void {
  $f=$this->fixture();$repo=new PublishReviewRepository();$context=$repo->inspect($f['input']);self::assertNotWPError($context);$old=$_GET;try{$_GET=['df_view'=>'listings','df_shop'=>'digital'];foreach($f['input']as $key=>$value)if($key!=='shop_key')$_GET['df_publish_'.$key]=(string)$value;$html=(new DigiForge\Portal\Portal())->render();$directory=getenv('DF_PORTAL_FIXTURE_DIR');if(is_string($directory)&&$directory!=='')self::assertSame(strlen($html),file_put_contents($directory.'/portal-listings--digital.html',$html));self::assertStringContainsString($context['scope_hash'],$html);self::assertStringContainsString('CONFIRM_SEPARATE_PUBLISH_REVIEW',$html);self::assertStringContainsString('grants no activation or execution permission',$html);}finally{$_GET=$old;}
  $result=PortalActionAcceptanceFixture::invoke('PUBLISH_REVIEW_ACTION',$f['input']+['scope_hash'=>$context['scope_hash'],'publish_review_confirmation'=>'CONFIRM_SEPARATE_PUBLISH_REVIEW'],false,false);self::assertArrayHasKey('df_publish_review',$result);$record=$repo->read($result['df_publish_review']);self::assertNotWPError($record);self::assertSame(get_current_user_id(),$record['payload']['actor_id']);self::assertSame($context['scope_hash'],$record['payload']['context']['scope_hash']);global $wpdb;self::assertSame(0,(int)$wpdb->get_var("SELECT COUNT(*) FROM ".$wpdb->prefix."digiforge_etsy_operations WHERE operation_type='PUBLISH_LISTING' AND intent_id=".$f['intent']));
 }
 public function testControllerRequiresSeparateReviewBeforeConnectorReadsUnderSyntheticEnabledQuery():void {
  $f=$this->fixture();global $wpdb;$filter=static function(string $sql):string{if(str_contains($sql,'SELECT setting_value, setting_type FROM '.Tables::settings()))return str_contains($sql,"'stop_all'")?"SELECT 'false' AS setting_value, 'boolean' AS setting_type":"SELECT 'true' AS setting_value, 'boolean' AS setting_type";return $sql;};$secrets=0;$watch=static function(string $sql)use(&$secrets):string{if(str_contains($sql,Tables::integration_secrets()))++$secrets;return $sql;};$r=new WP_REST_Request('POST','/digiforge/v1/etsy/publish-listing');$r->set_header('Content-Type','application/json');$r->set_header('Idempotency-Key','missing-separate');$body=$f['input'];unset($body['shop_key']);$r->set_body(wp_json_encode($body));add_filter('query',$filter);add_filter('query',$watch);try{$result=(new DigiForge\REST\EtsyPublishExecutionController())->execute($r);self::assertWPError($result);self::assertSame('digiforge_etsy_publish_separate_review',$result->get_error_code());self::assertSame(0,$secrets);}finally{remove_filter('query',$filter);remove_filter('query',$watch);}
 }
 public function testCallerContextInjectionExpiredAndDifferentActorCannotReuseReview():void {
  $f=$this->fixture();$repo=new PublishReviewRepository();$context=$repo->inspect($f['input']);self::assertNotWPError($context);$review=$repo->record($f['input'],$context['scope_hash'],'CONFIRM_SEPARATE_PUBLISH_REVIEW');self::assertNotWPError($review);$id=$review['payload']['review_id'];self::assertWPError($repo->consume($id,array_replace($context,['request_fingerprint'=>hash('sha256','forged')]),'forged-context'));
  $expired=$review;$expired['payload']['issued_at']=time()-301;$expired['payload']['expires_at']=$expired['payload']['issued_at']+300;$expired['seal']=hash_hmac('sha256',DigiForge\Listings\Validator::canonicalJson($expired['payload']),wp_salt('auth'));update_option(PublishReviewRepository::PREFIX.$id,wp_json_encode($expired),false);self::assertWPError($repo->verify($id,$context));update_option(PublishReviewRepository::PREFIX.$id,wp_json_encode($review),false);wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));self::assertWPError($repo->read($id));
 }
 public function testApprovedPrepublishCannotBindADifferentPackageAndBlockedDraftContractRemainsUnchanged():void {
  $f=$this->fixture();self::assertWPError((new DigiForge\Listings\EtsyDraftPreparation())->prepare($f['intent']));$pre=(new DigiForge\Listings\EtsyPrepublishPreparation())->prepare($f['intent'],$f['package']);self::assertNotWPError($pre);self::assertFalse($pre['publish_authorized']);$other=ReviewedListingFixture::create($this);self::assertWPError((new DigiForge\Listings\EtsyPrepublishPreparation())->prepare($f['intent'],$other['package']));
 }
 private function syntheticRequest(array $input,string $key,?string $review=null):WP_Error|WP_REST_Response {
  $filter=static function(string $sql):string{if(str_contains($sql,'SELECT setting_value, setting_type FROM '.Tables::settings()))return str_contains($sql,"'stop_all'")?"SELECT 'false' AS setting_value, 'boolean' AS setting_type":"SELECT 'true' AS setting_value, 'boolean' AS setting_type";return $sql;};$body=$input;unset($body['shop_key']);if($review!==null)$body['publish_review_id']=$review;$r=new WP_REST_Request('POST','/digiforge/v1/etsy/publish-listing');$r->set_header('Content-Type','application/json');$r->set_header('Idempotency-Key',$key);$r->set_body(wp_json_encode($body));add_filter('query',$filter);try{return (new DigiForge\REST\EtsyPublishExecutionController())->execute($r);}finally{remove_filter('query',$filter);}
 }
 public function testUnknownPublicationBlocksFreshKeysAcrossNewApprovedPackagesBeforeHttpOrReviewConsumption():void {
  $f=$this->fixture();$plan=DigiForge\Listings\EtsyPublishListingOperation::plan(1234,5678);self::assertNotWPError($plan);$ops=new DigiForge\Listings\EtsyOperationRepository();$record=$ops->createFromPayload(['shop_reference'=>'1234','intent_id'=>$f['intent'],'draft_package_id'=>$f['package'],'operation_type'=>'PUBLISH_LISTING','resource_reference'=>'5678','idempotency_key'=>'uncertain-'.wp_generate_uuid4(),'authorization_hash'=>hash('sha256','synthetic-previous-permit'),'evidence_hash'=>hash('sha256','synthetic-previous-evidence')],$plan['payload']);self::assertNotWPError($record);self::assertNotWPError($ops->transition((int)$record['id'],'SENT'));self::assertNotWPError($ops->transition((int)$record['id'],'UNKNOWN'));
  $other=$this->fixture();$repo=new PublishReviewRepository();$c=$repo->inspect($other['input']);self::assertNotWPError($c);$review=$repo->record($other['input'],$c['scope_hash'],'CONFIRM_SEPARATE_PUBLISH_REVIEW');self::assertNotWPError($review);$id=$review['payload']['review_id'];$result=$this->syntheticRequest($other['input'],'fresh-publish-key',$id);self::assertWPError($result);self::assertSame('digiforge_etsy_publish_reconciliation',$result->get_error_code());self::assertSame('CURRENT_LOCAL_DECISION',$repo->status($id)['state']);self::assertSame((int)$record['id'],(int)$ops->publishAttemptForResource('1234','5678')['id']);self::assertNull($ops->publishAttemptForResource('1234','9999'));global $wpdb;self::assertSame(0,(int)$wpdb->get_var("SELECT COUNT(*) FROM ".$wpdb->prefix."digiforge_etsy_operations WHERE idempotency_key='fresh-publish-key'"));
 }
 public function testRealCompetingConnectionHoldsTheShopPublishLockAndNoDispatchOccurs():void {
  $f=$this->fixture();$parts=explode(':',DB_HOST,2);$connection=new mysqli($parts[0],DB_USER,DB_PASSWORD,DB_NAME,isset($parts[1])?(int)$parts[1]:3306);self::assertSame(0,$connection->connect_errno);$lock='digiforge-publish-'.substr(hash('sha256','1234'),0,40);$query=$connection->prepare('SELECT GET_LOCK(?,0)');$query->bind_param('s',$lock);$query->execute();self::assertSame(1,(int)$query->get_result()->fetch_row()[0]);try{$result=$this->syntheticRequest($f['input'],'busy-scope');self::assertWPError($result);self::assertSame('digiforge_etsy_publish_busy',$result->get_error_code());}finally{$query=$connection->prepare('SELECT RELEASE_LOCK(?)');$query->bind_param('s',$lock);$query->execute();self::assertSame(1,(int)$query->get_result()->fetch_row()[0]);$connection->close();}
 }
 public function testPublishScopeLockAndOutstandingReadFailuresNeverInferPermission():void {
  $f=$this->fixture();$ops=new DigiForge\Listings\EtsyOperationRepository();$filter=static fn(string $sql):string=>str_contains($sql,"AND state<>'CONFIRMED_FAILURE'")?'SELECT * FROM missing_outstanding_publish_evidence':$sql;global $wpdb;$old=$wpdb->suppress_errors(true);add_filter('query',$filter);try{self::assertWPError($ops->publishAttemptForResource('1234','5678'));}finally{remove_filter('query',$filter);$wpdb->suppress_errors($old);}
  $filter=static fn(string $sql):string=>str_starts_with($sql,'SELECT GET_LOCK(')?'SELECT 0':$sql;add_filter('query',$filter);try{$result=$this->syntheticRequest($f['input'],'unavailable-lock');self::assertWPError($result);self::assertSame('digiforge_etsy_publish_busy',$result->get_error_code());}finally{remove_filter('query',$filter);}
 }
